import{_ as e}from"./chunks/proxy-auto-rules-card.D-DNY6Yl.js";import{_ as o}from"./chunks/options-network.BC245pY_.js";import{_ as r,o as s,c as a,a2 as i}from"./chunks/framework.CfwCq2QB.js";const n="/dev-go-docs/shots/0.2.3/en/light/popup-network.png",d="/dev-go-docs/shots/0.2.3/en/light/proxy-mode-card.png",b=JSON.parse('{"title":"Proxy & rule-based routing","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/proxy.md","filePath":"en/features/proxy.md"}'),h={name:"en/features/proxy.md"};function u(l,t,p,c,m,y){return s(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="proxy-rule-based-routing" tabindex="-1">Proxy &amp; rule-based routing <a class="header-anchor" href="#proxy-rule-based-routing" aria-label="Permalink to &quot;Proxy &amp; rule-based routing&quot;">​</a></h1><p>In one line: Direct / System proxy / Auto / Global proxy in one click, plus custom proxy modes — each mode keeps its own proxy server and bypass list.</p><h2 id="the-four-network-modes" tabindex="-1">The four network modes <a class="header-anchor" href="#the-four-network-modes" aria-label="Permalink to &quot;The four network modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td>Direct</td><td>No proxy</td></tr><tr><td>System proxy</td><td>Use system settings</td></tr><tr><td>Auto</td><td>Rule-based: matched sites go through the proxy, the rest follow your default</td></tr><tr><td>Global proxy</td><td>Everything goes through the proxy</td></tr></tbody></table><p>Entry points: the popup&#39;s Network page (<code>Alt+3</code>) to switch quickly; Settings → Network for full configuration.</p><img src="'+n+'" alt="The popup&#39;s Network page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Network page: switch modes in one click; set the current site to direct or proxied at the bottom.</em></p><img src="'+d+'" alt="The Network mode section in settings: four modes"><p><em>Settings → Network mode: switch among the four modes.</em></p><h2 id="per-site-shortcuts" tabindex="-1">Per-site shortcuts <a class="header-anchor" href="#per-site-shortcuts" aria-label="Permalink to &quot;Per-site shortcuts&quot;">​</a></h2><p>At the bottom of the popup&#39;s Network page:</p><ul><li><strong>Direct on this site</strong>: route one site around the proxy (a domestic site that misbehaves through your proxy, say)</li><li><strong>Proxy this site</strong>: route only the current site through the proxy (same effect as adding it to custom proxy domains in Auto — it takes priority over the rule list)</li></ul><h2 id="how-auto-works" tabindex="-1">How Auto works <a class="header-anchor" href="#how-auto-works" aria-label="Permalink to &quot;How Auto works&quot;">​</a></h2><p>Auto = rule list + custom proxy domains + a default for unmatched traffic:</p><ul><li><strong>Rule list</strong>: AutoProxy / GFWList format. When enabled, matched sites go through the proxy; updated automatically every 6 hours, or manually via &quot;Update / Download&quot;</li><li><strong>Custom proxy domains</strong>: sites that need the proxy but aren&#39;t in the rules — one domain per line, subdomains included</li><li><strong>When no rule matches</strong>: defaults to &quot;Direct&quot; (only matched sites use the proxy). If your proxy app handles its own routing, switch to &quot;Proxy&quot; — everything goes through except the bypass list, LAN, and <code>.cn</code> domains</li></ul><p>With no rules and no custom domains, Auto is equivalent to Direct.</p><img src="'+e+'" alt="The proxy configuration card in settings"><p><em>The &quot;Proxy configuration&quot; card — Direct and System proxy need no configuration; switch to Auto, Global proxy, or a custom mode to configure the proxy server, rule list, and bypass list here. (Screenshot shows the Chinese UI; an English version is pending.)</em></p><h2 id="custom-proxy-modes" tabindex="-1">Custom proxy modes <a class="header-anchor" href="#custom-proxy-modes" aria-label="Permalink to &quot;Custom proxy modes&quot;">​</a></h2><p>Beyond the built-ins, &quot;Add custom mode&quot; lets you name different proxy servers (&quot;Work&quot;, &quot;Home&quot;) and switch between them in one click. Each mode keeps its own proxy server (scheme / host / port) and bypass list.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Proxy server and bypass list</strong> changes need &quot;Save and apply&quot;; the rule list, proxy domains, and real IP protection take effect immediately</li><li>The proxy config bar sticks to the bottom, highlights unsaved changes, and confirms before you leave</li><li>Turn on &quot;Refresh the page after switching proxies&quot; so the current page reloads after a mode switch — no half-old connections</li><li>Once DevGo controls the proxy, the browser&#39;s extension card shows &quot;Controlled by DevGo&quot;; if it says another extension controls it, disable that extension first</li><li><strong>Firefox isn&#39;t supported yet</strong> (a Chromium-specific API limitation) — see the <a href="/dev-go-docs/en/faq/#proxy-switching-doesn-t-work-in-firefox">FAQ</a></li></ul><img src="'+o+'" alt="Network settings"><p><em>Settings → Network: proxy configuration, the rule list, and real IP protection, all on one page.</em></p>',24)])])}const w=r(h,[["render",u]]);export{b as __pageData,w as default};
